# Generated by the official offline native encoder from synthetic mission 42,
# partition/rooms below, and deterministic synthetic round UUIDs. No robot data.
OFFICIAL_VACUUM = b64decode(
    ""
)
OFFICIAL_MOP = b64decode(
    ""
)
PARTITION = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"
ROOMS = ["11111111-1111-4111-8111-111111111111", "22222222-2222-4222-8222-222222222222"]


def coverage(payload):
    return b(b(b(payload, 15), 1), 3)


@pytest.mark.parametrize(
    "official,second_mode", [(OFFICIAL_VACUUM, Mode.VACUUM), (OFFICIAL_MOP, Mode.MOP)]
)
def test_mixed_update_matches_official_bytes(official, second_mode):
    c = coverage(official)
    goals = bytes_fields(b(c, 5), 1)
    rounds = [UUID(uuid_string(b(b(g, 6), 1))) for g in goals]
    rounds += [UUID(int=900 + n) for n in range(16 - len(rounds))]
    session = UUID(uuid_string(b(c, 6)))
    ids = iter([*rounds, session, UUID(int=999), UUID(uuid_string(b(c, 7)))])
    commands = encode_mixed_coverage_commands(
        mission_id=42,
        partition_id=PARTITION,
        region_ids=ROOMS,
        settings=[Setting.QUICK, Setting.OPTIMAL],
        modes=[Mode.VACUUM, second_mode],
        command_id_factory=lambda: next(ids),
    )
    assert commands.update == official
    assert commands.session_id == str(session)
    initial = coverage(commands.initial)
    assert b(initial, 6) == b(c, 6)
    assert b(initial, 7) != b(c, 7)
    assert bytes_fields(b(initial, 5), 1)[:8] == goals[:8]


@pytest.mark.parametrize(
    "mode1,mode2,setting1,setting2", list(product(Mode, Mode, Setting, Setting))
)
def test_all_mode_setting_pairs_preserve_first_room(mode1, mode2, setting1, setting2):
    commands = encode_mixed_coverage_commands(
        mission_id=42,
        partition_id=PARTITION,
        region_ids=ROOMS,
        settings=[setting1, setting2],
        modes=[mode1, mode2],
    )
    initial, update = map(coverage, (commands.initial, commands.update))
    count = {Mode.VACUUM: 8, Mode.MOP: 4, Mode.BOTH: 12}
    before, after = [bytes_fields(b(c, 5), 1) for c in (initial, update)]
    assert len(after) == count[mode1] + count[mode2]
    assert before[: count[mode1]] == after[: count[mode1]]
    assert b(initial, 6) == b(update, 6)
    for goal in after[count[mode1] :]:
        spec = b(b(goal, 6), 3)
        assert (
            v(spec, 1)
            == {Setting.QUICK: 2, Setting.OPTIMAL: 1, Setting.HEAVY_DUTY: 0}[setting2]
        )
        assert v(spec, 4) in (
            {0, 1} if mode2 == Mode.BOTH else {0} if mode2 == Mode.VACUUM else {1}
        )
        if v(spec, 4) == 1:
            assert v(spec, 2) == 0


@pytest.mark.parametrize(
    "overrides",
    [
        {"region_ids": ROOMS[:1]},
        {"settings": []},
        {"modes": []},
        {"region_ids": [ROOMS[0], ROOMS[0]]},
        {"modes": ["unknown", Mode.VACUUM]},
        {"settings": ["unknown", Setting.QUICK]},
    ],
)
def test_mixed_rejects_invalid_inputs(overrides):
    args = {
        "mission_id": 42,
        "partition_id": PARTITION,
        "region_ids": ROOMS,
        "settings": [Setting.QUICK, Setting.OPTIMAL],
        "modes": [Mode.VACUUM, Mode.MOP],
    }
    args.update(overrides)
    with pytest.raises(ValueError):
        encode_mixed_coverage_commands(**args)


def test_mixed_groups_keep_legacy_recovery_boundaries():
    rooms = [
        CleaningRoom("one", "One", "vacuum", "quick"),
        CleaningRoom("two", "Two", "mop", "standard"),
        CleaningRoom("three", "Three", "vacuum_and_mop", "heavy_duty"),
    ]
    assert leg_groups(rooms, mixed_settings=True) == [rooms]
    assert leg_groups(rooms, mixed_settings=False) == [[r] for r in rooms]


@pytest.fixture
def mixed_client(monkeypatch):
    client = MaticHermesClient("robot.invalid", 16320)
    session = "33333333-3333-4333-8333-333333333333"
    identity = _wrapped_uuid(session)
    floor = FloorPlan(42, PARTITION, b"partition", ())
    monkeypatch.setattr(
        "custom_components.matic_robot.client.api.encode_mixed_coverage_commands",
        lambda **kwargs: MixedCoverageCommands(b"start", b"update", session),
    )
    client._async_send_user_payload = AsyncMock()
    client.async_get_cleaning_session_identity = AsyncMock(
        side_effect=[b"", identity, identity, identity]
    )
    client.async_get_state = AsyncMock(
        return_value=SimpleNamespace(
            activity=SimpleNamespace(value="cleaning"), current_area="the First"
        )
    )
    client.async_get_floor_plan = AsyncMock(return_value=floor)
    client.async_send_user_command = AsyncMock()
    return (
        client,
        identity,
        {
            "floor_plan": floor,
            "region_ids": ROOMS,
            "settings": [Setting.QUICK, Setting.OPTIMAL],
            "modes": [Mode.VACUUM, Mode.MOP],
            "first_room_name": "First",
            "require_current": Mock(),
            "require_owned": Mock(),
            "prepare_stop": AsyncMock(),
        },
    )


async def test_owned_update_sent_once(mixed_client):
    client, _, args = mixed_client
    await client.async_start_mixed_coverage(**args)
    assert [
        c.kwargs["command_name"]
        for c in client._async_send_user_payload.await_args_list
    ] == ["START_COVERAGE", "UPDATE_COVERAGE"]
    client.async_send_user_command.assert_not_awaited()


async def test_replacement_during_stop_fence_persistence_is_not_stopped(mixed_client):
    client, identity, args = mixed_client
    other = _wrapped_uuid("44444444-4444-4444-8444-444444444444")
    client.async_get_floor_plan = AsyncMock(
        return_value=FloorPlan(99, PARTITION, b"changed", ())
    )
    client.async_get_cleaning_session_identity = AsyncMock(
        side_effect=[b"", identity, identity, other]
    )
    with pytest.raises(MaticError, match="Room map changed"):
        await client.async_start_mixed_coverage(**args)
    args["prepare_stop"].assert_awaited_once()
    client.async_send_user_command.assert_not_awaited()


async def test_active_native_mission_rejects_initial_write(mixed_client):
    client, identity, args = mixed_client
    client.async_get_cleaning_session_identity = AsyncMock(return_value=identity)
    with pytest.raises(MaticError):
        await client.async_start_mixed_coverage(**args)
    client._async_send_user_payload.assert_not_awaited()


@pytest.mark.parametrize("after_write", [False, True])
async def test_identity_rechecked_around_update(mixed_client, after_write):
    client, identity, args = mixed_client
    other = _wrapped_uuid("44444444-4444-4444-8444-444444444444")
    reads = [b"", identity] + ([identity] if after_write else []) + [other, other]
    client.async_get_cleaning_session_identity = AsyncMock(side_effect=reads)
    with pytest.raises(MaticError, match="Native mission changed"):
        await client.async_start_mixed_coverage(**args)
    assert client._async_send_user_payload.await_count == (2 if after_write else 1)
    client.async_send_user_command.assert_not_awaited()


async def test_start_timeout_and_failed_recovery_never_update(
    mixed_client, monkeypatch
):
    client, _, args = mixed_client
    client.async_get_cleaning_session_identity = AsyncMock(
        side_effect=[b"", b"", MaticError("offline")]
    )
    monkeypatch.setattr(
        "custom_components.matic_robot.client.api.asyncio.sleep",
        AsyncMock(side_effect=TimeoutError),
    )
    with pytest.raises(TimeoutError):
        await client.async_start_mixed_coverage(**args)
    assert client._async_send_user_payload.await_count == 1
    client.async_send_user_command.assert_not_awaited()


