@pytest.mark.parametrize("failure", [None, "transport", "stop", "replacement"])
async def test_entity_mixed_dispatch_guards(hass, failure):
    from homeassistant.exceptions import HomeAssistantError

    from custom_components.matic_robot.plans import (
        PLAN_MOTION_TOKEN,
        CleaningPlanManager,
    )
    from custom_components.matic_robot.vacuum import MaticVacuum
    from tests.test_entities import _entry

    entry = _entry()
    manager = CleaningPlanManager(hass)
    manager._store = SimpleNamespace(async_save=AsyncMock())
    entry.runtime_data.cleaning_plans = manager
    token = manager.begin_managed_motion("synthetic-serial")

    async def send(*args, **kwargs):
        kwargs["require_owned"]()
        if failure == "transport":
            await kwargs["prepare_stop"]()
            raise MaticError("unavailable")
        if failure == "stop":
            manager.finish_room_event("synthetic-serial").set()
        if failure == "replacement":
            manager.replace_managed_motion("synthetic-serial")
        kwargs["require_current"]()

    client = entry.runtime_data.coordinator.client
    client.async_start_mixed_coverage = AsyncMock(side_effect=send)
    entity = MaticVacuum(entry)
    params = {
        "rooms": ["Kitchen", "Study"],
        "ordered": True,
        PLAN_MOTION_TOKEN: token,
        "room_coverage": ["quick", "standard"],
        "room_modes": ["vacuum", "mop"],
    }
    if failure:
        with pytest.raises((HomeAssistantError, MaticError)):
            await entity.async_send_command("clean_rooms", params)
    else:
        await entity.async_send_command("clean_rooms", params)
    client.async_start_coverage.assert_not_awaited()
    client.async_start_mixed_coverage.assert_awaited_once()


@pytest.mark.parametrize(
    "extra",
    [
        {"room_coverage": "quick"},
        {"room_modes": ["bad"]},
        {"room_coverage": ["quick", "standard"], "room_modes": ["vacuum", "mop"]},
    ],
)
async def test_entity_rejects_unowned_or_invalid_mixed_parameters(hass, extra):
    from homeassistant.exceptions import ServiceValidationError

    from custom_components.matic_robot.plans import CleaningPlanManager
    from custom_components.matic_robot.vacuum import MaticVacuum
    from tests.test_entities import _entry

    entry = _entry()
    entry.runtime_data.cleaning_plans = CleaningPlanManager(hass)
    with pytest.raises(ServiceValidationError):
        await MaticVacuum(entry).async_send_command(
            "clean_rooms", {"rooms": ["Kitchen", "Study"], **extra}
        )


async def test_runner_passes_each_rooms_mode_and_setting(hass):
    from homeassistant.core import ServiceCall

    from custom_components.matic_robot.services import _async_dispatch_leg_command

    captured = []

    async def send(call):
        captured.append(call.data)

    hass.services.async_register("vacuum", "send_command", send)
    rooms = [
        CleaningRoom("one", "One", "vacuum", "quick"),
        CleaningRoom("two", "Two", "mop", "standard"),
    ]
    await _async_dispatch_leg_command(
        hass, ServiceCall(hass, "matic_robot", "run", {}), "vacuum.test", rooms, 1, None
    )
    assert captured[0]["params"]["room_modes"] == ["vacuum", "mop"]
    assert captured[0]["params"]["room_coverage"] == ["quick", "standard"]


@pytest.mark.parametrize(
    "failure", ["replacement", "map", "update", "stop", "recovery_unknown"]
)
async def test_failed_update_cannot_replay_or_stop_replacement(mixed_client, failure):
    client, identity, args = mixed_client
    other = _wrapped_uuid("44444444-4444-4444-8444-444444444444")
    if failure == "replacement":
        client.async_get_cleaning_session_identity = AsyncMock(
            side_effect=[b"", other, other]
        )
    elif failure == "map":
        client.async_get_floor_plan = AsyncMock(
            return_value=FloorPlan(99, PARTITION, b"partition", ())
        )
        client.async_get_cleaning_session_identity = AsyncMock(
            side_effect=[b"", identity, identity, identity]
        )
    elif failure in ("update", "recovery_unknown"):
        client._async_send_user_payload.side_effect = [
            None,
            MaticError("update failed"),
        ]
        client.async_get_cleaning_session_identity = AsyncMock(
            side_effect=[
                b"",
                identity,
                identity,
                identity if failure == "update" else None,
                identity,
            ]
        )
    else:
        args["require_current"].side_effect = [None, None, MaticError("stop")]
        client.async_get_cleaning_session_identity = AsyncMock(
            side_effect=[b"", identity, identity]
        )
    with pytest.raises(MaticError):
        await client.async_start_mixed_coverage(**args)
    assert client._async_send_user_payload.await_count <= 2
    assert client.async_send_user_command.await_count == (
        0 if failure in ("replacement", "recovery_unknown") else 1
    )
